/* @arkzen:web:components:shared */

'use client'

import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react'
import { useRouter } from 'next/navigation'
import { useAuthStore } from '@/arkzen/core/stores/authStore'
import {
  Pencil, Eraser, Pipette, Move, Square, Circle, Minus,
  Type, Trash2, Plus, Eye, EyeOff, Lock, Unlock,
  ChevronDown, Play, Pause, SkipBack, SkipForward,
  Undo2, Redo2, Download, Share2, Settings, ArrowLeft,
  Layers, Palette, Sparkles, Film, Grid3x3, FlipHorizontal,
  FlipVertical, RotateCcw, Copy, Crosshair, PaintBucket as Bucket,
  Save, RefreshCw, Check, X
} from 'lucide-react'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface Pixel {
  [key: string]: string // "x,y" -> hex color
}

export interface Layer {
  id: string
  name: string
  visible: boolean
  locked: boolean
  opacity: number
  blendMode: string
  pixels: Pixel
}

export interface Frame {
  id: string
  duration: number // ms
  layers: Layer[]
}

export interface Project {
  id: number
  name: string
  width: number
  height: number
  thumbnail: string | null
  created_at: string
  updated_at: string
}

export type Tool =
  | 'pencil' | 'eraser' | 'fill' | 'eyedropper'
  | 'select' | 'move' | 'line' | 'rect' | 'circle' | 'text'

// ─── Constants ────────────────────────────────────────────────────────────────

export const PICO8_PALETTE = [
  '#000000','#1D2B53','#7E2553','#008751',
  '#AB5236','#5F574F','#C2C3C7','#FFF1E8',
  '#FF004D','#FFA300','#FFEC27','#00E436',
